using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace KianaPet {
 public static class HookSetup {
  public static string Home{get{return Environment.GetEnvironmentVariable("CODEX_HOME")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex");}}
  public static string Command(string exe,string root){if((exe+root).IndexOfAny(new[]{'"','\r','\n'})>=0)throw new ArgumentException("连接路径包含不支持的字符。");if(System.Text.RegularExpressions.Regex.IsMatch(exe+root,@"^[A-Za-z0-9_:.\\-]+$"))return exe+" --hook-event --hook-root \""+root+"\"";return "powershell.exe -NoLogo -NoProfile -NonInteractive -Command \"& '"+exe.Replace("'","''")+"' --hook-event --hook-root '"+root.Replace("'","''")+"'\"";}
  public static Dictionary<string,object> Merge(Dictionary<string,object> config,string command,string exe,string prototype){
   if(config==null)config=new Dictionary<string,object>();var hooks=MusicBridge.Get(config,"hooks") as Dictionary<string,object>;if(hooks==null){if(config.ContainsKey("hooks"))throw new Exception("现有 hooks 配置格式无法识别，未覆盖。");hooks=new Dictionary<string,object>();config["hooks"]=hooks;}
   foreach(string kind in HookJournal.Events){var groups=MusicBridge.Get(hooks,kind) as object[];if(hooks.ContainsKey(kind)&&groups==null)throw new Exception("现有 "+kind+" 格式无法识别，未覆盖。");var kept=new List<object>();foreach(var value in groups??new object[0]){var group=value as Dictionary<string,object>;var handlers=MusicBridge.Get(group,"hooks") as object[];if(group==null||handlers==null)throw new Exception("现有 Hooks 组格式无法识别，未覆盖。");var remaining=handlers.Where(h=>{string text=MusicBridge.Str(h,"command")+MusicBridge.Str(h,"commandWindows");return !(text.IndexOf(exe,StringComparison.OrdinalIgnoreCase)>=0&&text.Contains("--hook-event"))&&!(prototype!=null&&text.IndexOf(prototype,StringComparison.OrdinalIgnoreCase)>=0);}).ToArray();if(remaining.Length>0){var copy=new Dictionary<string,object>(group);copy["hooks"]=remaining;kept.Add(copy);}}
    kept.Add(new Dictionary<string,object>{{"hooks",new object[]{new Dictionary<string,object>{{"type","command"},{"command",command},{"commandWindows",command},{"timeout",3}}}}});hooks[kind]=kept.ToArray();
   }return config;
  }
  public static string Install(){string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"KianaHookReceiver.exe");if(!Maintenance.Installed())throw new Exception("请先安装桌宠，再注册稳定运行路径中的 Hooks。");string file=Path.Combine(Home,"hooks.json"),original=File.Exists(file)?File.ReadAllText(file):null;if(original!=null&&original.Length>2097152)throw new Exception("Hooks 配置过大，未修改。");var config=original==null?null:HookJournal.Json().DeserializeObject(original) as Dictionary<string,object>;if(original!=null&&config==null)throw new Exception("Hooks 配置无法识别，未覆盖。");string prototype=null;try{var binding=HookJournal.Json().DeserializeObject(File.ReadAllText(Path.Combine(Store.Root,"repository.json")));prototype=Path.Combine(MusicBridge.Str(binding,"RepositoryRoot"),"experiments","connections","HookReceiver.cjs");}catch{}
   config=Merge(config,Command(exe,HookJournal.Root),exe,prototype);string result=HookJournal.Json().Serialize(config);if(original==result)return file;if(original!=null)HookJournal.Atomic(Path.Combine(Store.Root,"connections","config-backups",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+"-hooks.json"),original);HookJournal.Atomic(file,result);return file;
  }
 }
 public sealed partial class SettingsWindow {
  ComboBox gptConnection,musicConnection;CheckBox backgroundMiniChoice;bool syncingConnections;
  void ConnectionChoice(Panel page,bool gpt){string[] values=gpt?new[]{"cdp","hooks","auto"}:new[]{"cdp","system","auto"};var box=new ComboBox{ItemsSource=gpt?new[]{"原有 Mini / 页面联动","本地 Hooks（普通启动）","自动：优先原有联动，失败后 Hooks"}:new[]{"原有播放器页面联动","Windows 系统媒体（普通启动）","自动：优先页面，失败后系统媒体"},SelectedIndex=Array.IndexOf(values,gpt?pet.Settings.GPTConnectionMode:pet.Settings.MusicConnectionMode),Padding=new Thickness(8),Margin=new Thickness(0,0,0,8)};System.Windows.Automation.AutomationProperties.SetName(box,gpt?"ChatGPT 连接方式":"网易云连接方式");box.SelectionChanged+=delegate{if(syncingConnections||box.SelectedIndex<0)return;if(gpt)pet.Settings.GPTConnectionMode=values[box.SelectedIndex];else pet.Settings.MusicConnectionMode=values[box.SelectedIndex];pet.ApplySettings();if(gpt)pet.ReconnectChatGPT();};page.Children.Add(box);if(gpt)gptConnection=box;else musicConnection=box;}
  void BuildGPTConnectionSettings(Panel page){TitleText(page,"ChatGPT 连接方式");ConnectionChoice(page,true);Note(page,"默认保留原有联动。Hooks 读取本机任务的运行、待处理、回合结束与中断事件；GPT 可先普通启动。首次注册或更新定义后，需要在 GPT 的 Hooks 设置中审核信任。云端任务、聊天/语音入口与任务跳转不由 Hooks 提供。回合结束不等于任务成功。自动模式仅在原有连接不可用时使用 Hooks。");page.Children.Add(Button("注册 / 更新本机 Hooks",delegate{try{string file=HookSetup.Install();MessageBox.Show("已写入："+file+"\n已备份原配置，保留其他 Hooks。请在 GPT 的 Hooks 设置中审核并信任这 7 项定义；无需重启 GPT。","Hooks 连接");}catch(Exception e){MessageBox.Show(e.Message,"Hooks 连接");}},false));}
  void BuildMusicConnectionSettings(Panel page){TitleText(page,"网易云连接方式");ConnectionChoice(page,false);Note(page,"系统媒体直接连接普通启动的网易云，读取歌名、歌手、封面与播放状态；播放按钮只在你点击时发送指令。歌曲 ID 为本地记录匹配结果，系统没有原生 ID；同名版本存在歧义时需重新确认。歌曲 ID 和总时长仅在本次启动后的最新记录与歌名、主歌手严格一致时补充。当前客户端可能不提供进度，此时仅使用平时听歌动作，同步歌词和副歌切换不可用。自动模式优先保留页面联动。切换方式不会重启网易云。");}
  void UpdateConnectionSettings(){if(backgroundMiniChoice!=null){backgroundMiniChoice.IsEnabled=pet.Settings.GPTConnectionMode!="hooks";backgroundMiniChoice.ToolTip="仅原有页面联动与自动模式使用 Mini；Hooks 不使用 Mini。";}syncingConnections=true;try{if(gptConnection!=null)gptConnection.SelectedIndex=Array.IndexOf(new[]{"cdp","hooks","auto"},pet.Settings.GPTConnectionMode);if(musicConnection!=null)musicConnection.SelectedIndex=Array.IndexOf(new[]{"cdp","system","auto"},pet.Settings.MusicConnectionMode);}finally{syncingConnections=false;}}
 }
}
